// Medical Law & Ethics Practice Test 5. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–4.
import {q, mix} from './q.js';
const TAM='Tamparo, Medical Law, Ethics, & Bioethics for the Health Professions', FREM='Fremgen, Healthcare Law and Ethics', RIT='Ritter & Graham, Medical Law & Professional Ethics';
const BASIC='The Basics: Medical Law, Ethics and Bioethics', LEGAL='The Legal Environment', HCE='The Health Care Environment', BIO='Bioethical Issues';

export default {
 id:'medical-law-ethics-5',
 event:'Medical Law & Ethics',
 title:'Practice Test 5',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Tamparo’s Medical Law, Ethics, & Bioethics, Fremgen’s Healthcare Law and Ethics, and Ritter & Graham’s Medical Law & Professional Ethics',
 plan:[{area:BASIC,weight:5},{area:LEGAL,weight:35},{area:HCE,weight:35},{area:BIO,weight:25}],
 questions:mix([
  q(BASIC,'A competent patient decides to refuse a recommended surgery after hearing the risks. Which ethical principle supports honoring this choice?','Autonomy',['Beneficence','Paternalism','Utilitarianism'],'A','Autonomy is the right of competent persons to make decisions about their own bodies and care.',FREM),
  q(BASIC,'Which ancient code, still echoed in modern pledges, includes the promise to help the sick and avoid harm?','The Hippocratic Oath',['The Code of Hammurabi','The Nuremberg Code','The Belmont Report'],'B','The Hippocratic Oath dates to ancient Greece and introduced ideals such as confidentiality and avoiding harm.',TAM),
  q(LEGAL,'In a few states, a patient who is even 1% at fault for their own injury cannot recover any damages. What is this rule called?','Contributory negligence',['Comparative negligence','Assumption of risk','Respondeat superior'],'C','Under pure contributory negligence, any fault by the plaintiff bars recovery; most states now use comparative negligence.',FREM),
  q(LEGAL,'Which legal rule requires certain contracts, such as a promise to pay another person’s debt, to be in writing?','The statute of frauds',['The statute of limitations','The doctrine of res ipsa loquitur','The Good Samaritan law'],'D','A third party’s promise to pay a patient’s bill must be written to be enforceable under the statute of frauds.',TAM),
  q(LEGAL,'A physician temporarily fills in for another physician who is on vacation. What is this substitute called?','A locum tenens physician',['An attending physician of record','A defendant physician','A peer review physician'],'A','“Locum tenens” means “holding the place”; the substitute takes on the same duty of care to patients.',TAM),
  q(LEGAL,'During which phase of a lawsuit do both sides gather facts through depositions, interrogatories and records requests?','Discovery',['Arraignment','Sentencing','Closing arguments'],'B','Discovery lets each side learn the evidence before trial, which often leads to settlement.',FREM),
  q(LEGAL,'A physician who did not treat the patient testifies about the accepted standard of care. What is this witness called?','An expert witness',['A fact witness','A character witness','A hostile witness'],'C','Expert witnesses give opinions based on specialized knowledge; fact witnesses testify only to what they saw or did.',FREM),
  q(LEGAL,'A patient tries to sue again over the same claim that a court already decided. Which doctrine blocks this?','Res judicata',['Res ipsa loquitur','Stare decisis','Respondeat superior'],'D','“The thing has been decided”: once a final judgment is made, the same parties cannot relitigate the same claim.',FREM),
  q(LEGAL,'A medical assistant falsely tells others aloud that a doctor is a drug abuser. Which tort is this?','Slander',['Libel','Battery','Fraud'],'A','Slander is spoken defamation; libel is written defamation. Both harm a person’s reputation with false statements.',TAM),
  q(LEGAL,'Which malpractice insurance policy covers incidents that happened during the policy period, even if the claim is filed later?','An occurrence policy',['A claims-made policy','A tail-only policy','An umbrella auto policy'],'B','Occurrence policies cover any incident during the policy years; claims-made policies cover only claims filed while active.',FREM),
  q(LEGAL,'In older law, a surgeon could be held liable for the errors of all staff in the operating room. What is this doctrine called?','The captain of the ship doctrine',['The borrowed servant doctrine','The doctrine of informed refusal','The fellow servant doctrine'],'C','This doctrine held surgeons responsible for everyone in the OR; many courts have since limited it.',TAM),
  q(LEGAL,'After a patient is injured by negligence, the spouse sues for the loss of companionship and support. What is this claim called?','Loss of consortium',['Wrongful birth','Breach of warranty','Abandonment'],'D','Loss of consortium compensates a spouse or family member for the loss of the injured person’s companionship.',FREM),
  q(LEGAL,'A patient dies from negligent care. Which type of lawsuit can the family bring?','A wrongful death action',['A wrongful life action','A qui tam action','A small claims action for rent'],'A','Wrongful death statutes let survivors sue for losses caused by a negligent death.',FREM),
  q(LEGAL,'Darling v. Charleston Community Memorial Hospital established that hospitals can be liable for what?','Failing to monitor the quality of care given by their medical staff',['Refusing to treat patients who cannot pay in an emergency','Sharing patient records with insurance companies','Charging higher prices for private rooms'],'B','This case established corporate negligence: hospitals have their own duty to oversee physicians and staff.',FREM),
  q(LEGAL,'A sponge left in surgery is found 4 years later. In many states, when does the statute of limitations begin?','When the injury was discovered or should have been discovered',['On the day of the original surgery, regardless of discovery','On the patient’s next birthday after the surgery','Only after the surgeon retires from practice'],'C','The discovery rule starts the time limit when the patient knew or reasonably should have known of the injury.',FREM),
  q(LEGAL,'Some states let a minor who shows enough maturity consent to certain care. What is this called?','The mature minor doctrine',['The emancipated adult rule','The parental rights doctrine','The age of consent waiver'],'D','Courts may allow mature minors to consent based on their understanding, even though they are not emancipated.',TAM),
  q(LEGAL,'A state grants a license to a physician based on passing a national board exam rather than a state exam. What is this called?','Licensure by endorsement',['Licensure by reciprocity','Licensure by certification','Licensure by registration'],'A','Endorsement accepts national board results; reciprocity accepts a license from another state with similar standards.',TAM),
  q(LEGAL,'In contract law, what is “consideration”?','Something of value exchanged between the parties',['A polite gesture of kindness toward the patient','The amount of time a patient waits for care','The written signature of a witness'],'B','Valid contracts need an offer, acceptance, consideration and parties with capacity; in health care, payment for services is consideration.',FREM),
  q(LEGAL,'Information a patient shares with a physician is protected from being disclosed in court in many cases. What is this called?','Privileged communication',['Hearsay evidence','Public record','Defamation'],'C','State laws protect certain confidential communications, though exceptions exist, such as when the patient sues.',TAM),
  q(LEGAL,'What is “voir dire” in a trial?','The process of questioning potential jurors to select the jury',['The judge’s final ruling on the case','The closing argument made by the defense attorney','The written complaint filed by the plaintiff'],'D','During voir dire, attorneys and the judge question potential jurors to find possible bias.',FREM),
  q(HCE,'Under the HIPAA Breach Notification Rule, how soon must affected patients be notified of a breach?','Without unreasonable delay and no later than 60 days after discovery',['Within 1 year of the breach being discovered','Only if the patient asks about a breach first','Within 7 years, at the next record review'],'A','Breaches affecting 500 or more people must also be reported to HHS and the media.',FREM),
  q(HCE,'A home health aide suspects that an older adult is being neglected by family. To which agency is this usually reported?','Adult Protective Services',['The Drug Enforcement Administration','The Food and Drug Administration','The Internal Revenue Service'],'B','Most states require health workers to report suspected elder abuse or neglect to Adult Protective Services.',FREM),
  q(HCE,'Births and deaths must be reported to which office?','The state’s vital statistics office',['The hospital’s billing office','The Office for Civil Rights','The patient’s employer'],'C','Physicians and facilities file birth and death certificates with the state, which keeps vital records.',TAM),
  q(HCE,'How long are a minor’s medical records often kept?','Until the patient reaches the age of majority plus the statute of limitations',['Only until the child’s next birthday, after which the parents may keep them','Exactly 1 year after the last visit','Until the parent asks for them to be destroyed'],'D','Because minors may sue after reaching adulthood, records are kept longer; state laws set exact periods.',TAM),
  q(HCE,'Which feature of an electronic health record shows who viewed or changed a record and when?','The audit trail',['The problem list','The patient portal','The appointment scheduler'],'A','Audit trails help detect unauthorized access and are required under the HIPAA Security Rule.',FREM),
  q(HCE,'Under the Affordable Care Act, what may insurers no longer do?','Deny coverage because of a preexisting condition',['Charge any premium at all','Pay for preventive care','Cover dependents up to age 26'],'B','The ACA bans denying coverage or charging more for preexisting conditions and lets young adults stay on parents’ plans until 26.',FREM),
  q(HCE,'Which program mainly covers people 65 and older, and which mainly covers people with low income?','Medicare covers older adults; Medicaid covers low-income people',['Medicaid covers older adults; Medicare covers low-income people','Both programs cover only military veterans','Both programs cover only children under 18'],'C','Medicare is a federal program for those 65+ and some disabled people; Medicaid is a joint federal–state program.',FREM),
  q(HCE,'In an HMO, what role does the primary care provider usually play?','A gatekeeper who must approve referrals to specialists',['A billing clerk who collects payments','A judge who settles legal disputes','A pharmacist who fills prescriptions'],'D','HMOs control costs by requiring PCP referrals before patients see specialists.',FREM),
  q(HCE,'A provider is paid a fixed amount per patient each month, whether or not the patient is seen. What is this payment method?','Capitation',['Fee-for-service','Copayment','Coinsurance'],'A','Capitation pays per member per month and encourages providers to keep patients healthy and limit costs.',FREM),
  q(HCE,'Medicare pays hospitals a set amount based on the patient’s diagnosis. What is this system called?','Diagnosis-related groups (DRGs)',['Fee-for-service billing','Usual and customary fees','Out-of-pocket billing'],'B','DRGs are a prospective payment system: hospitals receive a fixed payment based on the diagnosis category.',FREM),
  q(HCE,'A nurse forgot to chart an event yesterday. How should it be documented today?','Labeled as a late entry with today’s date and time',['Written in the space for yesterday as if on time','Left out of the chart entirely','Written on a sticky note attached to the chart'],'C','Late entries must be clearly labeled and dated when written; backdating can look like falsifying records.',TAM),
  q(HCE,'A teacher reports suspected child abuse that turns out to be unfounded. What protects the teacher from being sued?','Good-faith immunity in state reporting laws',['The Stark Law on physician self-referral','The statute of frauds for written contracts','The Equal Pay Act'],'D','Mandatory reporters who act in good faith are protected from civil and criminal liability.',FREM),
  q(HCE,'Which American Hospital Association document explains what patients can expect during a hospital stay?','The Patient Care Partnership',['The Notice of Privacy Practices','The Nuremberg Code','The Hippocratic Oath'],'A','The Patient Care Partnership replaced the Patient’s Bill of Rights and describes patients’ rights and responsibilities.',TAM),
  q(HCE,'What is the main role of a hospital ethics committee?','To advise on difficult ethical cases and develop related policies',['To discipline employees who are late to work','To set the hospital’s room prices','To decide all malpractice lawsuits'],'B','Ethics committees help patients, families and staff work through dilemmas such as end-of-life decisions.',TAM),
  q(HCE,'How does health care “abuse” differ from “fraud”?','Abuse involves improper practices without proven intent to deceive',['Abuse always involves physical harm to a patient','Abuse is a crime, while fraud is only an ethical issue','Abuse only applies to pharmacy errors'],'C','Fraud is intentional deception for gain; abuse includes practices such as billing for unnecessary services without clear intent.',FREM),
  q(HCE,'A provider is on the OIG exclusion list. What does this mean?','They cannot bill federal health programs such as Medicare and Medicaid',['They have been named an outstanding provider of the year','They are required to see only private-pay patients for free','They must pass a new state board exam every month'],'D','Hiring or billing for excluded individuals can lead to large penalties for health care organizations.',FREM),
  q(HCE,'A computer automatically logs off after a period of inactivity. Under the HIPAA Security Rule, what kind of safeguard is this?','A technical safeguard',['A physical safeguard','An administrative safeguard','A financial safeguard'],'A','Technical safeguards include automatic log-off, encryption, passwords and audit controls.',FREM),
  q(HCE,'For how long after a person’s death does HIPAA continue to protect their health information?','50 years',['1 year','10 years','100 years'],'B','HIPAA protects a deceased person’s PHI for 50 years after death.',FREM),
  q(BIO,'In which study were Black men with syphilis left untreated for decades without informed consent?','The Tuskegee syphilis study',['The Willowbrook hepatitis study','The Framingham Heart Study','The Human Genome Project'],'C','The Tuskegee study (1932–1972) led to major reforms, including the Belmont Report and IRB requirements.',TAM),
  q(BIO,'Cells taken from Henrietta Lacks without her knowledge became a famous research cell line. Which ethical issue does this case raise?','Consent and ownership of human tissue used in research',['The legality of physician-assisted suicide','Rationing of organs for transplant','The use of placebos in drug trials'],'D','HeLa cells were taken in 1951 without consent and used widely, raising questions about consent and benefit to families.',TAM),
  q(BIO,'What is reproductive cloning?','Creating a genetically identical organism that is born',['Creating stem cells only for research or treatment','Freezing embryos for later IVF use','Testing embryos for genetic diseases'],'A','Reproductive cloning aims to produce a living individual; therapeutic cloning creates cells for treatment.',TAM),
  q(BIO,'Which advance directive states which treatments a person wants or refuses if they become terminally ill and unable to speak?','A living will',['A durable power of attorney for finances','A last will and testament','An organ donor card only'],'B','A living will states treatment wishes; a healthcare power of attorney names a person to make decisions.',TAM),
  q(BIO,'Which form turns a seriously ill patient’s treatment wishes into portable medical orders that EMS can follow?','POLST (Physician Orders for Life-Sustaining Treatment)',['A HIPAA authorization form','A living will kept only at home','An informed consent form for surgery'],'C','POLST forms are signed medical orders that travel with the patient across care settings.',TAM),
  q(BIO,'A physician gives a lethal injection to end a patient’s suffering. What is this called?','Active euthanasia',['Passive euthanasia','Palliative care','Physician-assisted suicide'],'D','In active euthanasia, someone else directly causes death; it is illegal throughout the United States.',TAM),
  q(BIO,'Which was the first U.S. state to legalize medical aid in dying through its Death with Dignity Act?','Oregon',['Texas','Florida','New York'],'A','Oregon’s Death with Dignity Act took effect in 1997 and allows terminally ill adults to obtain a lethal prescription.',TAM),
  q(BIO,'In some countries, everyone is considered an organ donor unless they register a refusal. What is this system called?','Presumed consent (opt-out)',['Required request (opt-in)','Directed donation','Mandated choice'],'B','The U.S. uses an opt-in system; countries such as Spain use opt-out to increase donation.',TAM),
  q(BIO,'Gene therapy that changes only a patient’s body cells, not eggs or sperm, is called what?','Somatic gene therapy',['Germline gene therapy','Reproductive cloning','Eugenic selection'],'C','Somatic changes affect only the treated person and are not passed to children.',TAM),
  q(BIO,'A surrogate decides what an incapacitated patient would have chosen based on the patient’s known values. Which standard is this?','Substituted judgment',['Best interest standard','Reasonable physician standard','Comparative negligence'],'D','Substituted judgment uses the patient’s own values; the best interest standard is used when those wishes are unknown.',TAM),
  q(BIO,'A trial compares two treatments when experts are genuinely uncertain which is better. What is this uncertainty called?','Clinical equipoise',['Therapeutic privilege','Double effect','Medical futility'],'A','Equipoise makes it ethical to randomly assign patients, since neither treatment is known to be superior.',TAM),
  q(BIO,'A competent adult Jehovah’s Witness refuses a blood transfusion during surgery. What must the team generally do?','Respect the refusal and use alternatives when possible',['Give the transfusion anyway to save the patient’s life','Ask a court to order the transfusion for the adult','Discharge the patient from care immediately'],'B','Competent adults may refuse treatment for religious reasons; courts may intervene for minors.',TAM)
 ],9509)
};
